t.script:
document.addEventListener('DOMContentLoaded', function() {
    const resultsDiv = document.getElementById('results');

    function showResult(message, isSuccess = true) {
        const alertClass = isSuccess ? 'alert-success' : 'alert-danger';
        resultsDiv.innerHTML = `<div class="alert ${alertClass}">${message}</div>`;
    }

    // Enable notifications
    document.getElementById('enableNotifications').addEventListener('click', function() {
        fetch('/web/dataset/call_kw', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    model: 'res.users',
                    method: 'write',
                    args: [[], {'firebase_notifications_enabled': true}],
                    kwargs: {}
                }
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result) {
                showResult('✓ Firebase notifications enabled successfully!');
                setTimeout(() => location.reload(), 1500);
            } else {
                showResult('✗ Failed to enable notifications', false);
            }
        })
        .catch(error => {
            showResult('✗ Error: ' + error.message, false);
        });
    });

    // Register token
    document.getElementById('registerToken').addEventListener('click', function() {
        const token = document.getElementById('tokenInput').value;
        if (!token) {
            showResult('✗ Please enter a token', false);
            return;
        }

        fetch('/firebase_notify/simple_register', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    token: token
                }
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result && data.result.success) {
                showResult('✓ Token registered successfully!');
                setTimeout(() => location.reload(), 1500);
            } else {
                showResult('✗ Failed to register token: ' + (data.result ? data.result.error : 'Unknown error'), false);
            }
        })
        .catch(error => {
            showResult('✗ Error: ' + error.message, false);
        });
    });

    // Send test notification
    document.getElementById('sendTest').addEventListener('click', function() {
        fetch('/firebase_notify/send_test', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {}
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result && data.result.success) {
                showResult('✓ Test notification sent successfully!');
            } else {
                showResult('✗ Failed to send notification: ' + (data.result ? data.result.error : 'Unknown error'), false);
            }
        })
        .catch(error => {
            showResult('✗ Error: ' + error.message, false);
        });
    });

    // Send test message
    document.getElementById('sendMessage').addEventListener('click', function() {
        fetch('/web/dataset/call_kw', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    model: 'mail.message',
                    method: 'create',
                    args: [{
                        'subject': 'Test Message for Firebase Notification',
                        'body': 'This is a test message to trigger Firebase notifications.',
                        'message_type': 'comment',
                        'partner_ids': [[6, 0, []]]
                    }],
                    kwargs: {}
                }
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result) {
                showResult('✓ Test message created! Check if you received a notification.');
            } else {
                showResult('✗ Failed to create test message', false);
            }
        })
        .catch(error => {
            showResult('✗ Error: ' + error.message, false);
        });
    });
});
